"""Build the image-only and genuine mixed-script logo experiments."""
from pathlib import Path
from html import escape
import json,re
R=Path(__file__).resolve().parents[1]
E=R/'explorations/round-03'
WORDS={'hindi':{'initial':['दम','E','Odisha'],'middle':['Dum','ए','Odisha'],'end':['Dum','E','ओडिशा']},'odia':{'initial':['ଦମ୍','E','Odisha'],'middle':['Dum','ଏ','Odisha'],'end':['Dum','E','ଓଡ଼ିଶା']}}
LANG={'hindi':'hi','odia':'or'}
PRIMARY={'hindi':'initial','odia':'end'}
def shell(title,body,script=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} — Dum E Odisha</title><link rel="icon" href="../../assets/logo/favicon.png"><link rel="stylesheet" href="round.css"><script src="round.js" defer></script></head><body data-script="{script}"><a class="skip" href="#main">Skip to content</a><header class="topbar"><a class="brand" href="../../index.html">DUM E ODISHA</a><nav class="toplinks" aria-label="Round 03"><a href="reference-study.html">Reference study</a><a href="index.html">These three ideas</a></nav></header><main id="main" class="wrap">{body}<footer><a href="../index.html">All brand explorations ←</a><span>Round 03 / 17 October 2026 / draft for review</span></footer></main></body></html>'''
for script,positions in WORDS.items():
 for position,words in positions.items():
  index={'initial':0,'middle':1,'end':2}[position]
  typeset=''.join(f'<span class="{"native" if i==index else "connector" if i==1 else "latin"}" lang="{LANG[script] if i==index else "en"}">{word}</span>' for i,word in enumerate(words))
  title=' '.join(words)
  art=f'''<article class="logo-art {script}" aria-label="{title}"><img class="icon" src="assets/handi-host.png" alt="Handi Host pictorial symbol"><div class="name-form"><div class="name-line">{typeset}</div></div></article>'''
  (E/f'{script}-{position}-artwork.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} / editable logo composition</title><link rel="stylesheet" href="round.css"></head><body class="logo-export-page"><div class="art-toolbar"><a href="{script}.html">← Back to this experiment</a><p>1600 × 700 px / exact live Unicode lettering with local licensed fonts. Edit the HTML source to refine the composition. The character is a placed raster illustration.</p></div><div class="art-window">{art}</div></body></html>''')
  # Pure-wordmark alternative retains the same letterforms and position; no symbol.
  if position==PRIMARY[script]:
   (E/f'{script}-wordmark-artwork.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} / wordmark only</title><link rel="stylesheet" href="round.css"></head><body class="logo-export-page"><div class="art-toolbar"><a href="{script}.html">← Back to experiment</a><p>1600 × 700 px / wordmark-only alternative, live typeset name.</p></div><div class="art-window">{art.replace('<img class="icon" src="assets/handi-host.png" alt="Handi Host pictorial symbol">','')}</div></body></html>''')
cards=[('handi-host','The Handi Host','Image only / no lettering','handi-host.png','A welcoming cooking-pot character. Lid, steam, rice and a confident open palm carry the idea without a single letter.'),('hindi','The Hindi beginning','Hindi + English','hindi-initial.png','दम begins the name in Devanagari. English carries E Odisha. Compare initial, middle and final-word experiments.'),('odia','The Odia ending','English + Odia','odia-end.png','Dum E leads into ଓଡ଼ିଶା. A regional-script ending makes the place name the distinctive part of the identity.')]
html_cards=''.join(f'''<article class="concept"><a class="preview" href="{slug}.html"><img src="assets/{asset}" alt="{escape(title)} logo experiment"></a><div><p class="eyebrow">0{i+1} / {label}</p><h2>{title}</h2><p>{description}</p><a class="view" href="{slug}.html">Explore this logo ↗</a></div></article>''' for i,(slug,title,label,asset,description) in enumerate(cards))
body=f'''<div class="intro"><p class="eyebrow">Round 03 / From your latest reference</p><h1>A picture.<br>Two new ways to say the name.</h1><p class="lead">One purely pictorial logo, then two mixed-script experiments. Choose a card to inspect the idea, compare name positions and download the artwork.</p><div class="links"><a href="reference-study.html">See what we observed in your screenshot ↗</a><a href="../dum-club-refinement/index.html">Previous Dum Club refinement ↗</a></div></div><div class="collection">{html_cards}</div><section class="section"><div class="two-col"><div><p class="eyebrow">The shared thinking</p><h2>Character first.<br>Script with purpose.</h2><p>The reference’s isolated birds, animals and confident silhouettes informed the economy of the Handi Host. Its pot, rice and lifted lid bring that approach back to biryani. The two lettering treatments use whole name units in Hindi or Odia, keeping the spoken name Dum E Odisha.</p></div><div><h3>What you can compare</h3><p>The symbol works alone. Each script page has three placements: initial Dum, middle E, or final Odisha. Primary recommendations are Hindi at the beginning and Odia at the end. A wordmark-only export is also included for each.</p><p class="note">The character is generated raster artwork with a hand-inked appearance. The mixed-script name is genuine typeset text. These are review experiments; native-reader approval is pending.</p></div></div></section>'''
(E/'index.html').write_text(shell('A pictorial logo and two mixed-script experiments',body))
body='''<div class="intro"><p class="eyebrow">01 / A purely pictorial logo</p><h1>The Handi Host.</h1><p class="lead">A welcoming host, drawn as the vessel at the heart of dum cooking. No font, no written name, no initials.</p></div><div class="two-col"><figure class="hero-panel"><img class="symbol-main" src="assets/handi-host.png" alt="Image-only Handi Host: welcoming biryani pot with lifted saffron lid, steam, rice details and an open palm"></figure><div><span class="tag">Image logo / lettering-free</span><h2>Come in.<br>The handi is open.</h2><p>The open palm suggests hospitality. The raised lid and steam show the dum-cooking moment. Three rice shapes anchor the picture in biryani, while the rounded pot gives it a friendly, grounded silhouette.</p><p>The compact character follows the reference’s strong mascot silhouettes. Its subject and pose are newly developed for Dum E Odisha.</p><div class="links"><a href="assets/handi-host.png" download>Transparent colour PNG ↓</a><a href="assets/handi-stamp-source.png" download>One-ink stamp PNG ↓</a></div></div></div><section class="section"><p class="eyebrow">A companion, simplified for ink</p><h2>Less detail.<br>The same welcome.</h2><div class="two-col"><figure style="background:white;padding:30px"><img src="assets/handi-stamp-source.png" alt="Simplified one-ink Handi Host with white face and rice knockouts"></figure><div><p>The stamp drawing removes the colour shading and reduces the face to broad knockouts. It keeps the lid, welcoming palm, rice and squat pot.</p><p>This is a separately generated simplified interpretation; its contours differ from the colour artwork. The white-background stamp file is supplied honestly as a raster concept.</p><p class="note">Use the full-colour character for larger digital placements. The simplified symbol is the better starting point for a seal, stamp or small avatar. The 48–128 px proofs below show what survives.</p></div></div></section><section class="section"><p class="eyebrow">Actual-size proof</p><h2>Recognisable when small.</h2><div class="small-proof"><figure><img src="assets/handi-host.png" width="128" height="128" alt="Colour Handi Host at 128 pixels"><figcaption class="caption">Colour / 128 px</figcaption></figure><figure><img src="assets/handi-stamp-source.png" width="96" height="96" alt="Stamp interpretation at 96 pixels"><figcaption class="caption">Stamp / 96 px</figcaption></figure><figure><img src="assets/handi-stamp-source.png" width="48" height="48" alt="Stamp interpretation at 48 pixels"><figcaption class="caption">Stamp / 48 px stress test</figcaption></figure></div><p class="caption">At 48 px the welcoming silhouette remains; the facial highlights and rice details need more room. Prefer at least 96 px for this raster stamp illustration. Reconstruct and physically proof a simplified vector before print production.</p></section><section class="section"><p class="eyebrow">The picture in a brand setting</p><h2>A friendly presence<br>on a big screen.</h2><figure><img class="image-full" src="assets/host-display.png" alt="Handi Host brand display: large pictorial mark beside Flavour in Every Layer"></figure><p class="caption">The pictorial logo remains lettering-free. The separate screen message and brand name are supporting layout text.</p><div class="links"><a href="host-display.html">Open editable display ↗</a><a href="assets/host-display.png" download>1600 × 900 PNG ↓</a></div></section><section class="section"><h2>The identity around it.</h2><div class="swatches"><span>Terracotta / #943B2B</span><span>Saffron / #EAAA37</span><span>Leaf / #294B3C</span></div><p>Use warm cream as the resting field, terracotta for readable information and saffron as an accent. Crop the character only in supporting graphics; keep the complete symbol in a seal or avatar. Give the face and open hand room.</p><div class="links"><a href="hindi.html">Pair it with Hindi + English ↗</a><a href="odia.html">Pair it with English + Odia ↗</a></div></section>'''
(E/'handi-host.html').write_text(shell('The Handi Host / image-only logo',body))
for script in WORDS:
 is_hi=script=='hindi';primary=PRIMARY[script];name='Hindi' if is_hi else 'Odia';label=' '.join(WORDS[script][primary])
 rationale='The opening word दम gives the name a compact, confident Devanagari anchor. E Odisha stays in Latin, so the name feels mixed by design rather than split into two competing translations.' if is_hi else 'The ending ଓଡ଼ିଶା gives the place name pride of place. Dum E stays in Latin; the rounded Odia forms become the memorable finish rather than a tiny translation beneath the logo.'
 buttons=''.join(f'<button type="button" data-position="{p}" data-label="{escape(" ".join(words))}" aria-pressed="{str(p==primary).lower()}">{p.title()} word</button>' for p,words in WORDS[script].items())
 rows=''.join(f'<tr><td>{p.title()} / {list(["Dum","E","Odisha"])[{"initial":0,"middle":1,"end":2}[p]]}</td><td><span lang="{LANG[script]}" class="{script}-serif" style="font-size:24px">{escape(" ".join(words))}</span></td><td><a href="assets/{script}-{p}.png" download>PNG ↓</a></td></tr>' for p,words in WORDS[script].items())
 body=f'''<div class="intro"><p class="eyebrow">0{'2' if is_hi else '3'} / A mixed-script logo experiment</p><h1>The {name} {'beginning' if is_hi else 'ending'}.</h1><p class="lead">{rationale}</p></div><figure class="script-preview"><img id="script-logo" src="assets/{script}-{primary}.png" alt="{label} mixed-script logo"></figure><p class="evidence-label" id="script-reading">{label}</p><div class="choices" role="group" aria-label="Choose which word uses {name}">{buttons}</div><div class="links"><a id="script-download" href="assets/{script}-{primary}.png" download>Download selected transparent PNG ↓</a><a id="editable-link" href="{script}-{primary}-artwork.html">Open live typeset artwork ↗</a></div><section class="section"><div class="two-col"><div><p class="eyebrow">Why it works</p><h2>{'One strong opening.' if is_hi else 'Let the place name lead.'}</h2><p>{'The substantial Devanagari strokes match the confident Latin serif weight. A quiet saffron rule grounds the name, while the separate illustration provides the welcoming tone. Neither the lid nor a graphic cuts across a matra.' if is_hi else 'Leaf green lets the rounded Odia forms feel considered and grounded. The Hindi-style headline is not imposed on Odia; its own marks, circles and spacing stay intact. The terracotta connector and saffron rule link it to the warm food identity.'}</p><p>Each experiment changes one whole name unit. Read all three as Dum E Odisha. The symbol can sit alongside the name or work alone.</p></div><div><h3>Compare all three positions</h3><div class="comparison-table"><table><thead><tr><th>Word in {name}</th><th>Exact proposed name</th><th>Export</th></tr></thead><tbody>{rows}</tbody></table></div></div></div></section><section class="section"><p class="eyebrow">An alternative without the illustration</p><h2>Let the lettering<br>carry the identity.</h2><figure class="script-preview"><img src="assets/{script}-wordmark.png" alt="{label} mixed-script wordmark without a pictorial symbol"></figure><div class="links"><a href="assets/{script}-wordmark.png" download>Transparent wordmark PNG ↓</a><a href="{script}-wordmark-artwork.html">Open editable wordmark composition ↗</a></div></section><section class="section"><h2>Script comes before decoration.</h2><p>The artwork uses local Noto Serif {'Devanagari' if is_hi else 'Oriya'} plus Georgia for Latin. Native words remain whole Unicode strings, including the {'vowel signs' if is_hi else 'virama, vowel signs and nukta sequence'}. The HTML sources preserve the lettering; PNG exports capture the browser’s actual shaping.</p><p class="note">These are proposed transliterations and visual experiments. A qualified {name} reader has not yet reviewed pronunciation, preferred name spelling or typographic balance. That review should happen before adoption.</p><div class="links"><a href="../fonts/provenance.json">Font provenance & license records ↗</a><a href="../type-lab.html">Earlier full-script type lab ↗</a><a href="handi-host.html">The standalone pictorial symbol ↗</a></div></section>'''
 (E/f'{script}.html').write_text(shell(f'{name} + English / three word positions',body,script))
body='''<div class="intro"><p class="eyebrow">Close observation / Your latest screenshot</p><h1>Illustration with<br>a clear silhouette.</h1><p class="lead">Your screenshot is a long Dribbble results page headed “Hindi logo”. It contains several different design languages; the title alone does not make every result a Hindi design.</p></div><div class="reference-grid"><figure><a href="references/inspection-0.png"><img src="references/inspection-0.png" alt="Top reference crop with the Hindi logo search heading, lettering studies and isolated marks"></a><figcaption class="caption">Search heading, expressive wordmarks and type variations.</figcaption></figure><figure><a href="references/inspection-1.png"><img src="references/inspection-1.png" alt="Reference crop showing a pig mascot, geometric birds, banana icon and positive-negative silhouettes"></a><figcaption class="caption">Illustrated subjects, limited palettes and economical silhouettes.</figcaption></figure></div><section class="section"><h2>What we actually observed.</h2><div class="two-col"><div><h3>Picture-led marks</h3><p>The pig, birds, horse, hippo and small animal portraits are recognisable isolated subjects. Their few strong shapes and deliberate knockout spaces give them character. The banana and plate/food symbols show that an everyday object can become a compact mark too.</p><h3>Lettering studies</h3><p>Juko, Veli, Summer and Blitz appear in multiple treatments. This is a method of comparing weight, terminals and rhythm, rather than simply picking a font and stopping. The gold Indic-looking mark near the top is a visual reference; its exact name is not verified here.</p></div><div><h3>How that becomes this work</h3><p>A pot host uses the illustrated-symbol approach for a biryani brand. A separate stamp interpretation tests silhouette and empty spaces. The two name experiments vary the position of one Hindi or Odia word while keeping the full brand name and actual script shaping.</p><h3>What remains original</h3><p>No pictured animal, bird, character, wordmark or distinctive silhouette was traced. The screenshot guides the presentation, economy and expressive direction. The Handi Host is a new generated character concept, not a claim of trademark clearance.</p></div></div></section><div class="links"><a href="references/owner-reference.png">Open the full supplied screenshot ↗</a><a href="sources/generation-prompts.json">Prompts, tools & provenance ↗</a><a href="index.html">Compare the three experiments ↗</a></div>'''
(E/'reference-study.html').write_text(shell('Reference observations / Round 03',body))
(E/'host-display.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Handi Host / editable display</title><link rel="stylesheet" href="round.css"></head><body><div class="art-toolbar"><a href="handi-host.html">← Back to the pictorial logo</a><p>1600 × 900 px / the symbol stays image-only; supporting brand copy sits separately. Click the headline to edit.</p></div><div class="art-window"><article class="display"><div class="picture"><img src="assets/handi-host.png" alt="Handi Host image-only symbol"></div><div class="message"><p>Dum E Odisha</p><h1 contenteditable="true" aria-label="Editable brand headline">Flavour in<br>Every Layer.</h1><p class="foot">Biryani / Bhubaneswar<br>@dum_e_odisha</p></div></article></div></body></html>''')
(E/'sources/script-matrix.json').write_text(json.dumps({'brand':'Dum E Odisha','status':'draft_native_review_pending','primary':PRIMARY,'proposals':WORDS,'fontSources':'../../fonts/provenance.json','invariants':['Three name units remain Dum E Odisha','Whole words change script; no hybrid pseudo-glyphs','No marks or matras removed for decoration']},ensure_ascii=False,indent=2)+'\n')
# Durable main-guide and root-portal entries.
guide=R/'index.html';s=guide.read_text()
fragment='''<section id="symbol-script-round"><div class="section-head"><div><p class="eyebrow">Latest / Image-only & mixed-script logos</p><h2>A picture.<br>Two ways to say the name.</h2></div><p>A lettering-free Handi Host, a Hindi beginning and an Odia ending. Open each idea to compare initial, middle and final-word script placements.</p></div><div class="idea-grid food-grid">'''+''.join(f'<article class="idea-card"><a href="explorations/round-03/{slug}.html"><img src="explorations/round-03/assets/{asset}" alt="{title} logo experiment"><span>{label}</span><h3>{title}</h3><p>View the idea & download artwork ↗</p></a></article>' for slug,title,label,asset,_ in cards)+'''</div><div class="downloads"><a href="explorations/round-03/index.html">Compare the three new experiments ↗</a></div></section>'''
if 'id="symbol-script-round"' in s:s=re.sub(r'<section id="symbol-script-round">.*?</section>',lambda _:fragment,s,count=1,flags=re.S)
else:s=s.replace('<main id="main">','<main id="main">'+fragment,1)
s=s.replace('href="#dum-club-refinement">Explore ideas','href="#symbol-script-round">Explore ideas');guide.write_text(s)
portal=R.parents[1]/'index.html';s=portal.read_text();url='brand-system/review-v2/explorations/round-03/index.html'
if url not in s:s=s.replace('<h2>Make & use</h2>','<h2>Make & use</h2><a href="'+url+'">New: pictorial logo, Hindi & Odia hybrids</a>',1)
portal.write_text(s)
print('Built three experiment guides, six mixed-script artwork sources, two pure wordmarks, display, reference study and portal links.')
